parameters.jsCode:
// 6.4.1.1 - Rule-engine node (usage/tenure/adoption thresholds)
// FLAG: no upsell/cross-sell threshold rubric exists anywhere in the uploads (Stage 47 -
// Upsell Identification - is marked pilot-depth 'built' at the business-doc level per §10B row 47,
// but that automation.md content wasn't included in this upload, so the exact numbers below are
// NOT sourced from it - they are transparent placeholders modeled on the shape of a healthy-account
// rule (good health score + meaningful tenure + adoption checklist completed). Review against the
// real Stage 47 automation.md before treating this as final.
const a = $input.item.json;

const HEALTH_THRESHOLD = 70;      // placeholder
const TENURE_MIN_DAYS = 90;       // placeholder
const REQUIRE_ADOPTION_DONE = true;

const passes = {
  health: a.health_score !== null && a.health_score >= HEALTH_THRESHOLD,
  tenure: a.tenure_days !== null && a.tenure_days >= TENURE_MIN_DAYS,
  adoption: REQUIRE_ADOPTION_DONE ? !!a.adoption_checklist_created_at : true
};

const isCandidate = passes.health && passes.tenure && passes.adoption;

return [{
  json: {
    ...a,
    rule_engine_passes: passes,
    rule_engine_thresholds_status: 'PLACEHOLDER - not sourced from Stage 47 automation.md, needs confirmation',
    is_upsell_candidate: isCandidate
  }
}];

