={{ JSON.stringify({
  model: $vars.OLLAMA_MODEL || 'qwen2.5:14b',
  format: 'json',
  stream: false,
  prompt: `A client has passed internal health/tenure/adoption thresholds and is a candidate for an upsell or cross-sell conversation. Given only the service line they are currently on, suggest ONE plausible next-step service or expansion area a sales rep could raise with them, and a one-sentence rationale. Return ONLY valid JSON: {"suggestion": string, "rationale": string}. Do not invent specific pricing or make promises - this is a conversation-starter for a human rep, not a quote.\n\nCurrent service_type: ${$json.service_type || 'unknown'}\nTenure (days): ${$json.tenure_days}\nHealth score: ${$json.health_score}`
}) }}

parameters.jsCode:
let suggestion = {};
try { suggestion = JSON.parse($json.response); }
catch (e) { suggestion = { suggestion: 'Ollama output could not be parsed - manual review needed', rationale: '', parse_error: true }; }

return [{
  json: {
    ...$('Rule Engine - Thresholds').item.json,
    upsell_suggestion: suggestion.suggestion,
    upsell_rationale: suggestion.rationale,
    suggestion_parse_error: !!suggestion.parse_error
  }
}];

